// Parity with the shared runner spec: the extension must reproduce spec/runner/fixtures/expected.json,
// generated by ctx-run (the reference). Same check as tools/ctx-run/tests/test_runner_spec_parity.py.
const { test } = require('node:test');
const assert = require('node:assert');
const fs = require('fs');
const path = require('path');
const { buildSystemPrompt, buildUserMessage, buildFixPrompt, parseLlmResponse, buildScenarioResult } = require('../../out/ctxRunner.js');
const { cacheKey } = require('../../out/cache.js');

const dir = path.join(__dirname, '..', '..', '..', 'spec', 'runner', 'fixtures');
const cases = JSON.parse(fs.readFileSync(path.join(dir, 'cases.json'), 'utf-8'));
const expected = JSON.parse(fs.readFileSync(path.join(dir, 'expected.json'), 'utf-8'));

for (const c of cases) {
  test(`parity: ${c.id}`, () => {
    const e = expected[c.id];
    assert.strictEqual(buildSystemPrompt(), e.system, 'system prompt');
    assert.strictEqual(buildUserMessage(c.scenario, c.sourcePath, c.sourceContent, c.sourceWarning, c.language), e.user, 'user prompt');
    assert.strictEqual(cacheKey(c.scenario, c.sourceContent, c.model), e.key, 'cache key');
    const result = buildScenarioResult(c.scenario, c.raw, parseLlmResponse(c.raw));
    assert.deepStrictEqual(
      { name: result.name, overall_passed: result.overall_passed, error: result.error, steps: result.steps },
      e.result, 'parsed result');
    const failed = result.steps.filter((s) => !s.passed);
    assert.strictEqual(buildFixPrompt(c.scenario, failed, c.sourcePath, c.sourceContent, c.language), e.fix, 'fix prompt');
  });
}
